from typing import List

def validateBinaryTreeNodes(n: int, leftChild: List[int], rightChild: List[int]) -> bool:
    if n == 1:
        return leftChild[0] == -1 and rightChild[0] == -1

    children = set()
    for l, r in zip(leftChild, rightChild):
        if l != -1:
            children.add(l)
        if r != -1:
            children.add(r)

    if len(children) != n - 1:
        return False

    root_candidates = set(range(n)) - children
    if len(root_candidates) != 1:
        return False

    root = root_candidates.pop()

    visited = set()
    stack = [root]
    while stack:
        node = stack.pop()
        if node in visited:
            return False
        visited.add(node)
        l = leftChild[node]
        r = rightChild[node]
        if l != -1:
            stack.append(l)
        if r != -1:
            stack.append(r)

    return len(visited) == n
